{
  "Core Conclusion": {
    "claim": "Docker Compose 的重启策略可让容器在崩溃后自动恢复，但这不是自愈的充分条件；后端系统的‘自愈’结论置信度上限为低",
    "confidence_cap": "低（≤35%，依据弱于下文最弱依据层）"
  },
  "Epistemic Breakdown": {
    "axiom": {
      "label": "[L0] Docker Compose restart policy 的行为由文档与设计契约定义",
      "statement": "Docker Compose 支持 restart: unless-stopped / always / on-failure，容器进程退出或崩溃后由 Docker daemon 重新调度。",
      "status": "axiom（先验规则，不需要本系统观测来验证）",
      "confidence": 0.97
    },
    "observed_evidence": {
      "label": "[L1] 你或团队曾观察到容器退出后被重启",
      "statement": "例如 docker compose ps 显示 Restarting / Up，或日志中出现 Started container 事件。",
      "status": "observed evidence（基于特定环境、时间点、配置的观测）",
      "confidence": 0.85
    },
    "heuristic": {
      "label": "[L2] restart policy + 健康检查 ≈ 后端自愈（经验法则）",
      "statement": "很多团队把 container restart 当作后端自愈的近似指标，但重启不等于应用状态恢复、依赖恢复或流量正常。",
      "status": "heuristic（对一部分系统成立，非普遍规律）",
      "confidence": 0.55
    },
    "conclusion": {
      "label": "[L3] Docker Compose always restarts failed containers, so backend is self-healing",
      "statement": "原句把 restart 行为直接等价为自愈，属于过度泛化。",
      "confidence_cap": 0.35,
      "reason": "conclusion 的置信度不能超过 heuristic 层（0.55）与 evidence 层（0.85）的加权交集，且因缺少系统级验证，上限压低至低置信。"
    }
  },
  "Evidence Gaps": {
    "missing": [
      "未提供具体 restart policy 配置（always / unless-stopped / on-failure）",
      "未提供崩溃原因分类（业务异常、OOM、死锁、依赖不可用）",
      "未提供重启后健康检查结果（后端是否真正恢复服务，而非仅进程存活）",
      "未提供状态一致性验证（重启后数据库连接、缓存、内存状态、未完成事务是否可恢复）",
      "未提供对‘always restarts’的例外声明：容器被明确停止、daemon 未运行、配置错误、资源不足时不会重启",
      "未提供长期稳定性数据（重启次数、重启失败率、重启后的错误率）"
    ],
    "full_fix_plan_for_conclusion": {
      "claim_rewrite": "Docker Compose 配置了 restart: unless-stopped 时，容器进程异常退出会由 Docker daemon 自动重启；但自愈需要额外验证健康检查、依赖恢复与状态一致性，不能仅凭 restart policy 断言。",
      "required_changes": [
        "在 compose 文件中为后端服务添加 healthcheck（例如 curl /healthz，interval 5s, timeout 3s, retries 3）",
        "在 restart policy 中使用 unless-stopped 而非 always，避免人工停止也被重启",
        "为关键依赖（数据库、消息队列）添加 depends_on + condition: service_healthy 或 wait-for-it"
      ],
      "migration_impact": "compose 文件变更，服务定义增加 healthcheck 与 depends_on；无代码改动，但停机窗口内需重新创建容器（docker compose up -d --force-recreate）",
      "rollback_path": "git revert compose 文件到上一版本后执行 docker compose up -d；镜像不变，回退为无 healthcheck 的旧策略",
      "falsifiable_acceptance_criteria": [
        "人为 kill 容器主进程（docker kill <container>）后，容器在 30 秒内自动重启",
        "重启后 60 秒内 /healthz 返回 200",
        "连续 3 次人为 kill，后端在每次触发后都能通过健康检查",
        "如果后端因数据库不可用而崩溃，重启后不会无限重启；日志中断言依赖不可达而不是简单退出"
      ]
    }
  }
}

